#include <iostream>
#include <sstream>

int main() {
    std::istringstream input_stream("42");
    std::ostringstream prompt_stream;

    // Tie prompt_stream to input_stream
    input_stream.tie(&prompt_stream);

    prompt_stream << "Enter value: ";

    // Verify the tie
    if (input_stream.tie() == &prompt_stream) {
        std::cout << "Stream is tied to prompt_stream.\n";
    }

    int val = 0;
    input_stream >> val;

    std::cout << "Prompt content: " << prompt_stream.str() << "\n";
    std::cout << "Read value: " << val << "\n";

    // Untie using modern C++17 nullptr
    input_stream.tie(nullptr);
    if (input_stream.tie() == nullptr) {
        std::cout << "Stream successfully untied.\n";
    }

    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

int main() {
    // 1. Error state handling demonstration
    std::istringstream stream("invalid 100");
    int value = 0;
    stream >> value; // Fails to parse 'invalid' as integer

    if (stream.fail()) {
        std::cout << "Extraction failed as expected. failbit is set.\n";
        stream.clear(); // Clear error state
        std::string dummy;
        stream >> dummy; // Discard invalid string
    }

    stream >> value; // Successfully reads 100
    std::cout << "Recovered value: " << value << "\n";

    // 2. Manipulator formatting: base, justification, and setw
    std::cout << std::hex << std::showbase << std::uppercase;
    std::cout << "Hex: " << 255 << "\n";

    std::cout << std::dec << std::noshowbase;
    std::cout << std::setfill('*') << std::setw(8) << std::right << 42 << "\n";

    // 3. Unformatted I/O: write and read
    char text[] = " Antigravity";
    std::cout.write(text + 1, 11);
    std::cout << "\n";

    return 0;
}
